CREATE DATABASE IF NOT EXISTS pet_adoption_network CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE pet_adoption_network;
CREATE TABLE IF NOT EXISTS shelters(shelter_id INT AUTO_INCREMENT PRIMARY KEY,shelter_name VARCHAR(100) NOT NULL UNIQUE,address VARCHAR(200) NOT NULL,city VARCHAR(80) NOT NULL,contact_number VARCHAR(20) NOT NULL,email VARCHAR(120) UNIQUE,capacity INT NOT NULL CHECK(capacity>0),registration_date DATE NOT NULL DEFAULT (CURRENT_DATE)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS animals(animal_id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) NOT NULL,species VARCHAR(40) NOT NULL,breed VARCHAR(80),age DECIMAL(4,1) NOT NULL CHECK(age>=0),gender ENUM('Male','Female','Unknown') NOT NULL,size ENUM('Small','Medium','Large') NOT NULL,health_status VARCHAR(100) NOT NULL DEFAULT 'Healthy',vaccination_status ENUM('Vaccinated','Partially Vaccinated','Not Vaccinated') NOT NULL,shelter_id INT,current_status ENUM('Available','Fostered','Adopted') NOT NULL DEFAULT 'Available',registration_date DATE NOT NULL DEFAULT (CURRENT_DATE),special_needs VARCHAR(255),FOREIGN KEY(shelter_id) REFERENCES shelters(shelter_id) ON UPDATE CASCADE ON DELETE SET NULL,INDEX idx_animals_status(current_status),INDEX idx_animals_species_size(species,size)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS adopters(adopter_id INT AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(100) NOT NULL,age INT NOT NULL CHECK(age>=18),phone VARCHAR(20) NOT NULL UNIQUE,email VARCHAR(120) UNIQUE,address VARCHAR(200) NOT NULL,preferred_species VARCHAR(40),preferred_size ENUM('Small','Medium','Large','Any') NOT NULL DEFAULT 'Any',experience_with_pets ENUM('None','Beginner','Intermediate','Experienced') NOT NULL DEFAULT 'None',registration_date DATE NOT NULL DEFAULT (CURRENT_DATE)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS foster_homes(foster_id INT AUTO_INCREMENT PRIMARY KEY,foster_name VARCHAR(100) NOT NULL,phone VARCHAR(20) NOT NULL UNIQUE,email VARCHAR(120) UNIQUE,address VARCHAR(200) NOT NULL,maximum_capacity INT NOT NULL CHECK(maximum_capacity>0),availability_status ENUM('Available','Full','Inactive') NOT NULL DEFAULT 'Available') ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS fostering(foster_record_id INT AUTO_INCREMENT PRIMARY KEY,animal_id INT NOT NULL,foster_id INT NOT NULL,start_date DATE NOT NULL,expected_end_date DATE,actual_end_date DATE,foster_status ENUM('Active','Completed','Cancelled') NOT NULL DEFAULT 'Active',FOREIGN KEY(animal_id) REFERENCES animals(animal_id) ON DELETE RESTRICT,FOREIGN KEY(foster_id) REFERENCES foster_homes(foster_id) ON DELETE RESTRICT,UNIQUE KEY uq_animal_status(animal_id,foster_status),CHECK(expected_end_date IS NULL OR expected_end_date>=start_date),INDEX idx_foster_active(foster_id,foster_status)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS medical_records(medical_id INT AUTO_INCREMENT PRIMARY KEY,animal_id INT NOT NULL,examination_date DATE NOT NULL,diagnosis VARCHAR(255) NOT NULL,treatment VARCHAR(255),vaccination_details VARCHAR(255),next_checkup_date DATE,follow_up_status ENUM('Pending','Completed','Not Required') NOT NULL DEFAULT 'Not Required',FOREIGN KEY(animal_id) REFERENCES animals(animal_id) ON DELETE CASCADE,INDEX idx_medical_followup(next_checkup_date,follow_up_status)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS adoption_applications(application_id INT AUTO_INCREMENT PRIMARY KEY,animal_id INT NOT NULL,adopter_id INT NOT NULL,application_date DATE NOT NULL DEFAULT(CURRENT_DATE),application_status ENUM('Pending','Under Review','Approved','Rejected','Withdrawn') NOT NULL DEFAULT 'Pending',remarks VARCHAR(500),FOREIGN KEY(animal_id) REFERENCES animals(animal_id) ON DELETE RESTRICT,FOREIGN KEY(adopter_id) REFERENCES adopters(adopter_id) ON DELETE RESTRICT,INDEX idx_app_status(application_status)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS home_visits(visit_id INT AUTO_INCREMENT PRIMARY KEY,application_id INT NOT NULL,visit_date DATE NOT NULL,visit_status ENUM('Scheduled','Completed','Rejected','Rescheduled') NOT NULL DEFAULT 'Scheduled',observations VARCHAR(500),approval_recommendation ENUM('Recommended','Not Recommended','Pending') NOT NULL DEFAULT 'Pending',FOREIGN KEY(application_id) REFERENCES adoption_applications(application_id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS adoption_records(adoption_id INT AUTO_INCREMENT PRIMARY KEY,animal_id INT NOT NULL,adopter_id INT NOT NULL,application_id INT NOT NULL UNIQUE,adoption_date DATE NOT NULL DEFAULT(CURRENT_DATE),adoption_status ENUM('Completed','Cancelled') NOT NULL DEFAULT 'Completed',FOREIGN KEY(animal_id) REFERENCES animals(animal_id) ON DELETE RESTRICT,FOREIGN KEY(adopter_id) REFERENCES adopters(adopter_id) ON DELETE RESTRICT,FOREIGN KEY(application_id) REFERENCES adoption_applications(application_id) ON DELETE RESTRICT,UNIQUE KEY uq_success_animal(animal_id,adoption_status)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS medical_followup_alerts(alert_id INT AUTO_INCREMENT PRIMARY KEY,medical_id INT NOT NULL,alert_date DATE NOT NULL DEFAULT(CURRENT_DATE),alert_status ENUM('Pending','Resolved') NOT NULL DEFAULT 'Pending',remarks VARCHAR(255),FOREIGN KEY(medical_id) REFERENCES medical_records(medical_id) ON DELETE CASCADE,UNIQUE KEY uq_medical_alert(medical_id,alert_status)) ENGINE=InnoDB;
